import * as s from "../core/validation/index.js";
import type { EnumSchema } from "../core/validation/schema.js";

/**
 * | Attribute | Description | Data Type
 * | --- | ----------- | -------
 * | title | Product Title | string |
 * | sku | An arbitrary alphanumeric unique ID, seller-specified, identifying each item | string |
 * | itemId | Specifies the item identifier generated by Walmart | string |
 */
export const Field11 = {
  Title: "title",
  Sku: "sku",
  ItemId: "itemId",
} as const;
export type Field11 = (typeof Field11)[keyof typeof Field11] | (string & {});

export const field11Schema: EnumSchema<Field11> = s.enumOf<Field11>(Field11);
